  "def": "치주소파술은 잇몸병으로 깊어진 잇몸 주머니 안쪽 벽의 염증 조직을 긁어 내 정리하는 처치로, 잇몸이 다시 치아에 붙을 수 있는 환경을 만드는 것이 목적입니다.",
