  "def": "치성 감염은 충치나 잇몸병처럼 치아에서 시작된 세균 감염이 뿌리 끝이나 잇몸을 넘어 주변 뼈와 연조직, 얼굴 공간으로 퍼진 상태를 통틀어 이르는 말입니다.",
