  "def": "전문가 미백은 치과에서 잇몸을 보호한 뒤 비교적 높은 농도의 미백제를 치아에 바르고 정해진 시간 동안 반응시켜 치아 색을 밝히는 처치로, 짧은 기간에 변화를 확인하기 좋은 방법입니다.",
