  "def": "잇몸 미백(멜라닌 제거)은 잇몸에 갈색이나 검은색으로 침착된 멜라닌 색소를 레이저나 미세한 표면 제거로 걷어 내 잇몸을 분홍빛에 가깝게 개선하는 심미 처치입니다.",
