  "def": "비급여 진료는 국민건강보험이 적용되지 않아 진료비 전액을 환자가 부담하는 진료로, 치과에서는 임플란트(일부 제외), 교정, 라미네이트, 미백, 세라믹 크라운 등이 대표적입니다.",
