  "def": "통합치의학과는 한 분야에 치우치지 않고 충치·잇몸·보철·간단한 외과·예방 등 일차 치과 진료 전반을 통합적으로 진단하고 치료 계획을 세우는 치과 전문 분야로, 보건복지부가 인정하는 전문의 제도가 있습니다.",
